class IntegrationSkipObserver final:public Subscriber{
public:std::function<void(const Real *,Integer)> observe;
 IntegrationSkipObserver():Subscriber("IntegrationSkipObserver","IntegrationSkipObserver"){}
 ~IntegrationSkipObserver()override{Publisher::Instance()->Unsubscribe(this);}
 GmatBase *Clone()const override{return new IntegrationSkipObserver(*this);}
 bool ReceiveData(const Real *data,Integer count=0)override{if(data&&count>0&&observe)observe(data,count);return true;}
protected:bool Distribute(Integer)override{return true;}bool Distribute(const Real *,Integer)override{return true;}
};
static void reveal(QWidget *control){require(control,"Boundary sampling control missing");for(auto *p=control;p;p=p->parentWidget()){for(auto *tabs:control->window()->findChildren<QTabWidget *>())if(tabs->indexOf(p)>=0)tabs->setCurrentWidget(p);if(auto *scroll=qobject_cast<QScrollArea *>(p))scroll->ensureWidgetVisible(control);}events();require(control->isVisible()&&control->isEnabled(),"Boundary sampling input inaccessible");acceptanceView(*control);}
int main(int argc,char **argv){QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);QApplication app(argc,argv);app.setOrganizationName("GMATTests");app.setApplicationName("GroundIntegrationSkipBoundary");try{
 require(argc==2,"Supply startup");Rig rig(QFileInfo(argv[1]).absoluteFilePath());
 const QString mission="BeginMissionSequence;\nReport 'Arm boundary observer' Values Keep;\nPropagate 'First integration step' P(Sat) {Sat.ElapsedSecs = 10};\nPropagate 'Remaining steps' P(Sat) {Sat.ElapsedSecs = 600};\nReport Values Sat.ElapsedSecs Keep;\n";
 const QString script="Create Spacecraft Sat;\nSat.NAIFId = -10009997;\nSat.NAIFIdReferenceFrame = -9009997;\nSat.DateFormat = A1ModJulian;\nSat.Epoch = '21545';\nSat.CoordinateSystem = EarthMJ2000Eq;\nSat.DisplayStateType = Cartesian;\nSat.X = 7000;\nSat.Y = 0;\nSat.Z = 0;\nSat.VX = 0;\nSat.VY = "+number(std::sqrt(mu/7000.))+";\nSat.VZ = 0;\nCreate Variable Keep;\nKeep = 41;\nCreate ForceModel FM;\nFM.PrimaryBodies = {};\nFM.PointMasses = {Earth};\nFM.Drag = None;\nFM.SRP = Off;\nCreate Propagator P;\nP.FM = FM;\nP.InitialStepSize = 10;\nP.MinStep = 10;\nP.MaxStep = 10;\nP.Accuracy = 0.000000000001;\nCreate GroundTrackPlot Map;\nMap.Add = {Sat};\nMap.DataCollectFrequency = 4;\nMap.UpdatePlotFrequency = 1;\nMap.MaxPlotPoints = 1000;\nCreate ReportFile Values;\nValues.Filename = '"+rig.report+"';\nValues.WriteHeaders = false;\nValues.FixedWidth = false;\nValues.Delimiter = ',';\nValues.Precision = 25;\n"+mission;
 rig.source->setPlainText(script);require(rig.window.buildScript(),"Boundary fixture build failed");rig.save("baseline.script",script.toUtf8());auto matches=rig.resources->findItems("Map",Qt::MatchExactly|Qt::MatchRecursive);require(matches.size()==1,"Boundary GroundTrack resource missing");rig.resources->itemDoubleClicked(matches.front(),0);events();auto *child=rig.area->activeSubWindow();auto *panel=child?dynamic_cast<ResourceEditor *>(child->widget()):nullptr;require(panel,"Boundary primary GroundTrack form missing");auto *interval=panel->findChild<QSpinBox *>("ground_DataCollectFrequency");reveal(interval);interval->setFocus();QTest::keyClick(interval,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(interval,"2");QTest::keyClick(interval,Qt::Key_Tab);events();require(interval->value()==2&&panel->hasChanges()&&rig.source->toPlainText()==script,"Boundary interval draft isolation failed");QTest::mouseClick(panel->findChild<QDialogButtonBox *>("resourceButtons")->button(QDialogButtonBox::Apply),Qt::LeftButton);events();require(Moderator::Instance()->GetConfiguredObject("Map")->GetIntegerParameter("DataCollectFrequency")==2,"Boundary native interval differs");rig.closePanels();rig.save("applied.script",rig.source->toPlainText().toUtf8());
 Debugger *debug=nullptr;for(auto *o:rig.window.children())if(auto *d=dynamic_cast<Debugger *>(o))debug=d;require(debug,"Boundary debugger missing");const auto snapshot=rig.window.missionSnapshot();int arm=-1;for(int i=0;i<snapshot.nodes.size();++i)if(snapshot.nodes[i].statement.contains("Arm boundary observer"))arm=i;require(arm>=0&&rig.window.setBreakpoint(arm,true),"Boundary observer arm point missing");
 IntegrationSkipObserver observer;QJsonArray publications;QJsonObject violation;int ordinal=0,lastSelected=-1;quint64 lastFrame=0;bool subscribed=false;std::exception_ptr failure;
 observer.observe=[&](const Real *data,Integer count){if(failure)return;try{require(count>=7,"Boundary native publication incomplete");++ordinal;const double seconds=(data[0]-21545)*86400;const int step=int(std::llround(seconds/10));require(std::isfinite(seconds)&&std::abs(seconds-step*10)<.0001,"Boundary publication not on fixed integration grid");const auto truth=circular(orbits[0],seconds);QJsonArray state;for(int i=0;i<6;++i){require(std::isfinite(data[i+1])&&std::abs(data[i+1]-truth[i])<(i<3?.00003:.00000004),"Boundary raw state differs from independent circle");state.append(data[i+1]);}auto model=rig.window.plotReceiver()->model("Map");require(bool(model),"Boundary native receiver model missing");const bool selected=model->frame>lastFrame;publications.append(QJsonObject{{"publication",ordinal},{"elapsed",seconds},{"integration_step",step},{"frame",int(model->frame)},{"selected",selected},{"state",state}});rig.save("publications.json",QJsonDocument(publications).toJson());if(selected&&step!=lastSelected){if(lastSelected>=0&&step-lastSelected!=2){violation=QJsonObject{{"previous_collected_integration_step",lastSelected},{"collected_integration_step",step},{"requested_skipped_steps",1},{"actual_skipped_steps",step-lastSelected-1},{"native_interval",2},{"publication",ordinal}};rig.save("violation.json",QJsonDocument(violation).toJson());require(false,"NASA integration-step skip requirement violated at Propagate boundary");}lastSelected=step;}lastFrame=model->frame;events();}catch(...){failure=std::current_exception();QTimer::singleShot(0,&rig.window,[&]{rig.window.stopMission();});}};
 auto previous=debug->paused;debug->paused=[&](const QString &kind){if(previous)previous(kind);try{require(!subscribed&&kind=="Report","Boundary observer arm identity differs");auto model=rig.window.plotReceiver()->model("Map");require(model&&model->frame==0,"Boundary initial model not empty");bool backend=false;for(auto *subscriber:Publisher::Instance()->GetSubscriberList())if(subscriber->GetName()=="Map")backend=dynamic_cast<GroundTrack *>(subscriber)!=nullptr;require(backend&&Publisher::Instance()->Subscribe(&observer),"Boundary GroundTrack backend or observer missing");subscribed=true;}catch(...){failure=std::current_exception();QTimer::singleShot(0,&rig.window,[&]{rig.window.stopMission();});}QTimer::singleShot(0,&rig.window,[&]{debug->resume();});};
 QTimer watchdog;watchdog.setSingleShot(true);QObject::connect(&watchdog,&QTimer::timeout,&rig.window,&MainWindow::stopMission);watchdog.start(15000);const auto status=rig.window.runMission();watchdog.stop();debug->paused=previous;if(subscribed)Publisher::Instance()->Unsubscribe(&observer);events();rig.save("messages.txt",rig.messages->toPlainText().toUtf8());if(failure)std::rethrow_exception(failure);require(status==MainWindow::RunResult::Completed&&ordinal>=61,"Boundary mission did not complete");const QJsonObject proof{{"checkpoint","ground-integration-skip-boundary"},{"outcome","passed"},{"publications",publications},{"requested_skipped_steps",1},{"native_interval",2}};rig.save("proof.json",QJsonDocument(proof).toJson());std::cout<<"NASA_CHECK "<<QJsonDocument(proof).toJson(QJsonDocument::Compact).constData()<<std::endl;return 0;
 }catch(BaseException &e){std::cerr<<"FAIL "<<e.GetFullMessage()<<std::endl;}catch(std::exception &e){std::cerr<<"FAIL "<<e.what()<<std::endl;}return 1;}
